source("lib.R"); source("ziplib.R")
W <- mk(H("'i4'", "(1,)"), le(5L, 4), align = 16)
z <- zip_build(list(list(name = "ok.npy", data = npy_encode(1:3)), list(name = "odd.npy", data = W)))
ws <- list(); invisible(withCallingHandlers(npy_decode(z), warning = function(w) { ws[[length(ws) + 1]] <<- w; invokeRestart("muffleWarning") }))
for (w in ws) cat("warning class:", class(w)[1], "| fields:", names(w), "| message:", conditionMessage(w), "\n")
cat("== |u1 with huge / zero dims\n")
show("|u1 (0, 2147483647)", dim(npy_decode(mk(H("'|u1'", "(0, 2147483647)")))))
show("|u1 (0, 2147483648)", dim(npy_decode(mk(H("'|u1'", "(0, 2147483648)")))))
show("|u1 (2147483648, 0) file", dim(npy_decode(mk(H("'|u1'", "(2147483648, 0)")), order = "file")))
show("|u1 (0,)", npy_decode(mk(H("'|u1'", "(0,)")))); show("|u1 (0,) F", npy_decode(mk(H("'|u1'", "(0,)", TRUE))))
show("|u1 (1, 0, 1)", dim(npy_decode(mk(H("'|u1'", "(1, 0, 1)")))))
show("<U2 (0, 2)", dim(npy_decode(mk(H("'<U2'", "(0, 2)"))))); show("|V2 (2, 0)", dim(npy_decode(mk(H("'|V2'", "(2, 0)")))))
show("<M8[D] (0,)", npy_decode(mk(H("'<M8[D]'", "(0,)")))); show("<M8[Y] (0,)", class(npy_decode(mk(H("'<M8[Y]'", "(0,)")))))
show("<i8 (0,) integer64", class(npy_decode(mk(H("'<i8'", "(0,)")), int64 = "integer64")))
cat("== 10,000-member archive: time\n")
big <- setNames(lapply(1:10000, function(i) i), sprintf("m%05d", 1:10000)); zb <- npy_encode(big)
t <- system.time(r <- npy_decode(zb))[["elapsed"]]; cat("10000 members:", length(r), "in", round(t, 1), "s; names in order:", identical(names(r), names(big)), "values ok:", identical(unname(unlist(r)), as.numeric(1:10000)) || identical(unname(unlist(r)), 1:10000), "\n")
t <- system.time(r <- npy_decode(zb, names = c("m10000", "m00001")))[["elapsed"]]; cat("names= two of 10000:", names(r), "in", round(t, 2), "s\n")
big1 <- c(big, list(extra = 1L)); r <- try1(npy_decode(npy_encode(big1))); cat("10001 members default:", r$cls, "\n"); r <- try1(npy_decode(npy_encode(big1), max_members = 10001)); cat("10001 with max_members 10001:", r$ok, length(r$v), "\n")
